    long long minU = LLONG_MAX, maxU = LLONG_MIN;
    long long minV = LLONG_MAX, maxV = LLONG_MIN;
    int has = 0;

    for (int i = 0; i < N; i++) {
        long long u = U[i], v = V[i];
        if (u >= uL && u <= uR && v >= vL && v <= vR) continue;

        has = 1;
        if (u < minU) minU = u;
        if (u > maxU) maxU = u;
        if (v < minV) minV = v;
        if (v > maxV) maxV = v;
    }

    if (!has) return 1;
    return (maxU - minU <= D && maxV - minV <= D);
}

int feasible(long long D) {
    if (gMaxU - gMinU <= D && gMaxV - gMinV <= D) return 1;

    if (checkCorner(gMinU, gMinU + D, gMinV, gMinV + D, D)) return 1;
    if (checkCorner(gMaxU - D, gMaxU, gMinV, gMinV + D, D)) return 1;
    if (checkCorner(gMinU, gMinU + D, gMaxV - D, gMaxV, D)) return 1;
    if (checkCorner(gMaxU - D, gMaxU, gMaxV - D, gMaxV, D)) return 1;

    return 0;
}

