        int Y;
        scanf("%d", &Y);

        long long u = (long long)X[i] + Y;
        long long v = (long long)X[i] - Y;

        U[i] = u;
        V[i] = v;

        if (u < gMinU) gMinU = u;
        if (u > gMaxU) gMaxU = u;
        if (v < gMinV) gMinV = v;
        if (v > gMaxV) gMaxV = v;
    }

    free(X);

    long long lo = 0;
    long long hi = gMaxU - gMinU;
    if (gMaxV - gMinV > hi) hi = gMaxV - gMinV;

    while (lo < hi) {
        long long mid = lo + (hi - lo) / 2;
        if (feasible(mid)) {
            hi = mid;
        } else {
            lo = mid + 1;
        }
    }

    printf("%lld\n", lo);

    free(U);
    free(V);

    return 0;
}
